// Repository builds refresh canonical contracts. Owner copies retain portable snapshots.
import { readFile, writeFile } from "node:fs/promises";
for (const [name, target, header] of [
  [
    "app-gallery.ts",
    "generated-contract.ts",
    "// Generated by sync-contract.mjs from packages/contracts/src/app-gallery.ts. Do not edit.\n",
  ],
  [
    "app-gallery-inventory.ts",
    "generated-inventory.ts",
    "// Generated from packages/contracts/src/app-gallery-inventory.ts. Do not edit.\n",
  ],
]) {
  const canonical = new URL(
    `../../../packages/contracts/src/${name}`,
    import.meta.url,
  );
  const snapshot = new URL(`./src/${target}`, import.meta.url);
  try {
    const source = await readFile(canonical, "utf8");
    await writeFile(snapshot, header + source);
  } catch (error) {
    if (error?.code !== "ENOENT") throw error;
    const existing = await readFile(snapshot, "utf8");
    if (!existing.startsWith(header))
      throw new Error("Gallery contract snapshot unavailable");
  }
}
